    const wrapped = toError(reason);
    expect({message: wrapped.message, cause: wrapped.cause, isError: wrapped instanceof Error}).toEqual({
      message: JSON.stringify(reason),
      cause: reason,
      isError: true,
    });
    expect(toError(original)).toBe(original);
  });
});
